mapper.select:
SELECT

FROM car_confim_free t
left join sys_dept sd on sd.dept_id = t.org_id
WHERE t.del_flag = '0'
 and t.id = #{id}
 and t.car_id = #{carId}
 and t.car_no = #{carNo}
 and t.car_type = #{carType}
 and t.car_vehicle = #{carVehicle}
 and t.link_name like concat('%', #{linkName}, '%')
 and t.link_phone = #{linkPhone}
 and t.org_id = #{orgId}
 and sd.dept_name like concat('%', #{orgName}, '%')
 and t.user_ids = #{userIds}
 and t.user_names = #{userNames}
 and t.amount = #{amount}
 and t.escaped_types = #{escapedTypes}
 and t.back_col1 = #{backCol1}
 and t.back_col2 = #{backCol2}
 and t.status = #{status}
 and t.sort = #{sort}
 and t.eps_id = #{epsId}
 and t.tenant_id = #{tenantId}
 and t.create_by = #{createBy}
 and find_in_set(t.id,#{exceptIds}) > 0 
 and t.car_no like concat('%', #{carNoQuery}, '%')
and t.create_time >= STR_TO_DATE(#{applyTime1},'%Y-%m-%d %H:%i:%s')
and t.create_time <= STR_TO_DATE(#{applyTime2},'%Y-%m-%d %H:%i:%s') 

and t.create_time >= STR_TO_DATE(#{applyTime3},'%Y-%m-%d')
and t.create_time< date_add(STR_TO_DATE(#{applyTime4},'%Y-%m-%d'), interval 1 day) 

order by t.create_time desc,t.id

select  t.car_no,
t.car_type,
t.car_vehicle,
t.link_name,
t.link_phone,
t.org_id,
sd.dept_name org_name,
k.total_amount amount,
k.dif_amount aduit_amount,
k.except_ids
from car_info t JOIN
(select t1.car_no,sum(t1.total_amount) total_amount,sum(t1.charge_amount) charge_amount,sum(t1.dif_amount) dif_amount,
sum(case when t1.status = '0' then 1 else 0 end) except_num, GROUP_CONCAT(t1.id SEPARATOR ',') except_ids
from  car_except_record t1 where t1.del_flag = '0'
group by t1.car_no) k on k.except_num = 0 and t.car_no = k.car_no
left join sys_dept sd on sd.dept_id = t.org_id and sd.del_flag = '0'
WHERE t.del_flag = '0'
 and t.id = #{id}
 and t.car_id = #{carId}
 and t.car_no = #{carNo}
 and t.car_type = #{carType}
 and t.car_vehicle = #{carVehicle}
 and t.link_name like concat('%', #{linkName}, '%')
 and t.link_phone = #{linkPhone}
 and t.org_id = #{orgId}
 and sd.dept_name like concat('%', #{orgName}, '%')
 and t.user_ids = #{userIds}
 and t.user_names = #{userNames}
 and t.amount = #{amount}
 and t.escaped_types = #{escapedTypes}
 and t.back_col1 = #{backCol1}
 and t.back_col2 = #{backCol2}
 and t.status = #{status}
 and t.sort = #{sort}
 and t.eps_id = #{epsId}
 and t.tenant_id = #{tenantId}
 and t.create_by = #{createBy}
 and find_in_set(t.id,#{exceptIds}) > 0 
 and t.car_no like concat('%', #{carNoQuery}, '%')
and t.create_time >= STR_TO_DATE(#{applyTime1},'%Y-%m-%d %H:%i:%s')
and t.create_time <= STR_TO_DATE(#{applyTime2},'%Y-%m-%d %H:%i:%s')
